"use client";

import { useState, useCallback, useEffect } from "react";
import { useI18n } from "@/i18n/I18nContext";
import { axiosClient } from "@/lib/api/axiosClient";

export type LeadsView = "board" | "card" | "list";

export interface LeadStage {
  id: string;
  nameAr: string;
  nameEn: string;
  color: string;
}

export const LEAD_STAGES: LeadStage[] = [
  { id: "new", nameAr: "عميل جديد", nameEn: "New Lead", color: "border-slate-200" },
  { id: "contacted", nameAr: "تم التواصل", nameEn: "Contacted", color: "border-sky-200" },
  { id: "qualified", nameAr: "مؤهل", nameEn: "Qualified", color: "border-blue-200" },
  { id: "proposal", nameAr: "عرض سعر", nameEn: "Proposal", color: "border-purple-200" },
  { id: "negotiation", nameAr: "تفاوض", nameEn: "Negotiation", color: "border-amber-200" },
];

export interface LeadItem {
  id: string;
  leadName: string;
  company: string;
  email: string;
  phone: string;
  source: string;
  stageId: string;
  score: number;
  assignedTo: string;
  createdAt: string;
}

const mockLeads: LeadItem[] = [
  { id: "lead-101", leadName: "محمد عبدالله", company: "شركة الحياة الطبية", email: "dr.maliki@alhayat.sa", phone: "+966 50 888 9999", source: "Google Ads", stageId: "proposal", score: 85, assignedTo: "أحمد المبيعات", createdAt: "2026-07-20" },
  { id: "lead-102", leadName: "رامي خليل", company: "مؤسسة البناء الحديث", email: "rami@modern-con.com", phone: "+966 55 111 2222", source: "مكالمة واردة", stageId: "contacted", score: 62, assignedTo: "فاطمة العملاء", createdAt: "2026-07-22" },
  { id: "lead-103", leadName: "سارة المفلح", company: "مجموعة التجزئة", email: "sara@retail-adv.com", phone: "+966 54 333 4444", source: "Referral", stageId: "new", score: 40, assignedTo: "عمر التسويق", createdAt: "2026-07-25" },
];

export function useLeads() {
  const { t } = useI18n();
  const [activeView, setActiveView] = useState<LeadsView>("board");
  const [items, setItems] = useState<LeadItem[]>(mockLeads);
  const [searchQuery, setSearchQuery] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [selectedForDelete, setSelectedForDelete] = useState<LeadItem | null>(null);

  // Fetch Leads from Backend API with Mock Fallback
  const fetchLeads = useCallback(async () => {
    setIsLoading(true);
    try {
      const res = await axiosClient.get("/api/tenant/crm/v1/leads");
      if (res.data?.success && Array.isArray(res.data?.data)) {
        setItems(res.data.data);
      }
    } catch (err: any) {
      console.warn("Leads API fetch deferred, using mock fallback:", err?.message);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    void fetchLeads();
  }, [fetchLeads]);

  const filteredItems = items.filter(
    (item) =>
      item.leadName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.company.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.email.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleCreate = async (newItem: Omit<LeadItem, "id" | "score" | "createdAt" | "stageId">) => {
    const created: LeadItem = {
      ...newItem,
      id: `lead-${Date.now().toString().slice(-4)}`,
      score: 50,
      stageId: "new",
      createdAt: new Date().toISOString().split('T')[0],
    };

    setItems((prev) => [...prev, created]);
    setIsCreateOpen(false);

    try {
      await axiosClient.post("/api/tenant/crm/v1/leads", created);
    } catch (err: any) {
      console.warn("Lead creation API call deferred/mocked:", err?.message);
    }
  };

  const handleDelete = async () => {
    if (selectedForDelete) {
      const targetId = selectedForDelete.id;
      setItems((prev) => prev.filter((i) => i.id !== targetId));
      setSelectedForDelete(null);

      try {
        await axiosClient.delete(`/api/tenant/crm/v1/leads/${targetId}`);
      } catch (err: any) {
        console.warn("Lead deletion API call deferred/mocked:", err?.message);
      }
    }
  };

  const moveLead = async (leadId: string, destStageId: string, destIndex: number) => {
    setItems((prevItems) => {
      const itemIndex = prevItems.findIndex(item => item.id === leadId);
      if (itemIndex === -1) return prevItems;

      const newItems = [...prevItems];
      const [movedItem] = newItems.splice(itemIndex, 1);
      
      movedItem.stageId = destStageId;
      
      let insertGlobalIndex = 0;
      let stageCount = 0;
      for (let i = 0; i < newItems.length; i++) {
        if (newItems[i].stageId === destStageId) {
          if (stageCount === destIndex) {
            insertGlobalIndex = i;
            break;
          }
          stageCount++;
        }
        insertGlobalIndex = i + 1;
      }
      
      newItems.splice(insertGlobalIndex, 0, movedItem);
      return newItems;
    });

    try {
      await axiosClient.post(`/api/tenant/crm/v1/leads/${leadId}/stage`, {
        stageId: destStageId,
      });
    } catch (err: any) {
      console.warn("Lead move stage API call deferred/mocked:", err?.message);
    }
  };

  return {
    t,
    activeView,
    setActiveView,
    items: filteredItems,
    isLoading,
    searchQuery,
    setSearchQuery,
    isCreateOpen,
    setIsCreateOpen,
    selectedForDelete,
    setSelectedForDelete,
    handleCreate,
    handleDelete,
    moveLead,
    fetchLeads,
  };
}

"use client";

import { useState } from "react";
import { Modal } from "@/components/ui/Modal";
import { Input } from "@/components/ui/Input";
import { Select } from "@/components/ui/Select";
import { Button } from "@/components/ui/Button";
import { useI18n } from "@/i18n/I18nContext";

interface CreateModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: { title: string; targetType: "lead" | "deal" | "customer"; targetName: string; noteContent: string; attachmentName: string; fileSize: string; createdBy: string }) => void;
}

export function CreateCrmNotesAttachmentsModal({ isOpen, onClose, onSubmit }: CreateModalProps) {
    const { t } = useI18n();
  const [title, setTitle] = useState("");
  const [targetType, setTargetType] = useState<"lead" | "deal" | "customer">("deal");
  const [targetName, setTargetName] = useState(t.crm.alHayatHospitalDeal);
  const [noteContent, setNoteContent] = useState("");
  const [attachmentName, setAttachmentName] = useState("Document_V1.pdf");
  const [fileSize, setFileSize] = useState("1.5 MB");
  const [createdBy] = useState(t.crm.ahmedMahmoud);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return;
    onSubmit({ title, targetType, targetName, noteContent, attachmentName, fileSize, createdBy });
    setTitle("");
    setNoteContent("");
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={t.crm.addANewNoteAndAttachment} maxWidth="md">
      <form onSubmit={handleSubmit} className="space-y-4">
        <Input label={t.crm.noteTitle} placeholder={t.crm.exampleTechnicalMeetingDet} value={title} onChange={(e) => setTitle(e.target.value)} required />
        <div className="grid grid-cols-2 gap-3">
          <Select
            label={t.crm.associatedEntity}
            value={targetType}
            onChange={(e) => setTargetType(e.target.value as any)}
            options={[
              { label: t.crm.deal, value: "deal" },
              { label: t.crm.lead, value: "lead" },
              { label: t.crm.customerFile, value: "customer" },
            ]}
          />
          <Input label={t.crm.entityName} value={targetName} onChange={(e) => setTargetName(e.target.value)} required />
        </div>
        <div className="space-y-1.5">
          <label className="text-xs font-bold text-slate-700 dark:text-slate-300 block">{t.crm.noteContent}</label>
          <textarea
            rows={3}
            value={noteContent}
            onChange={(e) => setNoteContent(e.target.value)}
            className="w-full p-2.5 text-xs bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl"
            required
          />
        </div>
        <div className="grid grid-cols-2 gap-3">
          <Input label={t.crm.nameOfTheAttachedFile} value={attachmentName} onChange={(e) => setAttachmentName(e.target.value)} required />
          <Input label={t.crm.fileSize} value={fileSize} onChange={(e) => setFileSize(e.target.value)} required />
        </div>
        <div className="flex justify-end gap-2 pt-3 border-t border-slate-100 dark:border-slate-800">
          <Button type="button" variant="ghost" onClick={onClose}>{t.crm.cancellation}</Button>
          <Button type="submit" variant="primary">{t.crm.saveNote}</Button>
        </div>
      </form>
    </Modal>
  );
}

'use client';

import { useRef, useState } from 'react';
import { usePathname } from 'next/navigation';
import type { RTCSession } from 'jssip/lib/RTCSession';
import type { UA } from 'jssip';
import { playDtmfTone, iceServersFromSettings, isWebphoneReady, normalizeCallTarget } from '@mutakamel/webphone';
import { safeStorage } from "@/lib/safeStorage";
import type {
  AdminWebphoneConfig,
  AsteriskIntegrationSettings,
  WebphoneCallLog,
  WebphoneCallState,
  WebphoneConnectionState,
  WebphoneTab,
} from '@mutakamel/webphone';

type PhoneLifecycle = {
  connectPhone: () => Promise<void>;
  resetRemoteAudio: () => void;
  stopIncomingRingTone: () => void;
  stopLocalAudioStream: () => void;
};

const WEBPHONE_STORAGE_KEYS = {
  expanded: 'mutakamel.webphone.expanded',
  micVolume: 'mutakamel.webphone.micVolume',
  speakerVolume: 'mutakamel.webphone.speakerVolume',
} as const;

const idlePhoneLifecycle: PhoneLifecycle = {
  connectPhone: async () => undefined,
  resetRemoteAudio: () => undefined,
  stopIncomingRingTone: () => undefined,
  stopLocalAudioStream: () => undefined,
};

const keypad = [
  { value: '1', letters: '' },
  { value: '2', letters: 'ABC' },
  { value: '3', letters: 'DEF' },
  { value: '4', letters: 'GHI' },
  { value: '5', letters: 'JKL' },
  { value: '6', letters: 'MNO' },
  { value: '7', letters: 'PQRS' },
  { value: '8', letters: 'TUV' },
  { value: '9', letters: 'WXYZ' },
  { value: '*', letters: '' },
  { value: '0', letters: '+' },
  { value: '#', letters: '' },
] as const;

export function useWebRTCPhone() {
  const pathname = usePathname();
  const shouldActivate = typeof window !== 'undefined' && pathname !== '/login';

  const uaRef = useRef<UA | null>(null);
  const sessionRef = useRef<RTCSession | null>(null);
  const remoteAudioRef = useRef<HTMLAudioElement | null>(null);
  const localStreamRef = useRef<MediaStream | null>(null);
  const autoAnswerRef = useRef(false);
  const doNotDisturbRef = useRef(false);
  const phoneLifecycleRef = useRef<PhoneLifecycle>(idlePhoneLifecycle);

  const [expanded, setExpanded] = useState(() => readBooleanPreference(WEBPHONE_STORAGE_KEYS.expanded, false));
  const [incomingPopupDismissed, setIncomingPopupDismissed] = useState(false);
  const [activeTab, setActiveTab] = useState<WebphoneTab>('phone');
  const [settings] = useState<AsteriskIntegrationSettings>();
  const [webphone] = useState<AdminWebphoneConfig>();
  const [connectionState] = useState<WebphoneConnectionState>('idle');
  const [callState, setCallState] = useState<WebphoneCallState>('idle');
  const [status, setStatus] = useState('WebPhone');
  const [dialTarget, setDialTarget] = useState('');
  const [remoteParty] = useState('');
  const [muted, setMuted] = useState(false);
  const [speakerMuted, setSpeakerMuted] = useState(false);
  const [held, setHeld] = useState(false);
  const [autoAnswer, setAutoAnswerState] = useState(false);
  const [doNotDisturb, setDoNotDisturbState] = useState(false);
  const [callLogs] = useState<WebphoneCallLog[]>([]);
  const [logsLoading] = useState(false);

  const [micVolume, setMicVolumeState] = useState(() => readNumberPreference(WEBPHONE_STORAGE_KEYS.micVolume, 100));
  const [speakerVolume, setSpeakerVolumeState] = useState(() => readNumberPreference(WEBPHONE_STORAGE_KEYS.speakerVolume, 100));
  const [micLevel] = useState(0);
  const [speakerLevel] = useState(0);
  const [timerLabel] = useState('00:00');
  const [mediaNotice] = useState<string | null>(null);

  const setAutoAnswer = (enabled: boolean) => {
    autoAnswerRef.current = enabled;
    setAutoAnswerState(enabled);
  };

  const setDoNotDisturb = (enabled: boolean) => {
    doNotDisturbRef.current = enabled;
    setDoNotDisturbState(enabled);
  };

  const handleSetExpanded = (value: boolean | ((prev: boolean) => boolean)) => {
    setExpanded((prev) => {
      const next = typeof value === 'function' ? value(prev) : value;
      writePreference(WEBPHONE_STORAGE_KEYS.expanded, next);
      return next;
    });
  };

  const setMicVolumeLevel = (value: string | number) => {
    const next = Math.max(0, Math.min(100, typeof value === 'number' ? value : Number(value)));
    setMicVolumeState(next);
    writePreference(WEBPHONE_STORAGE_KEYS.micVolume, next);
  };

  const setSpeakerVolumeLevel = (value: string | number) => {
    const next = Math.max(0, Math.min(100, typeof value === 'number' ? value : Number(value)));
    setSpeakerVolumeState(next);
    writePreference(WEBPHONE_STORAGE_KEYS.speakerVolume, next);

    if (remoteAudioRef.current) {
      remoteAudioRef.current.volume = speakerMuted ? 0 : next / 100;
    }
  };

  const toggleMute = () => {
    const session = sessionRef.current;
    if (!session || !localStreamRef.current) {
      setMuted((prev) => !prev);
      return;
    }

    const targetState = !muted;
    localStreamRef.current.getAudioTracks().forEach((track) => {
      track.enabled = !targetState;
    });

    if (targetState) {
      session.mute({ audio: true, video: false });
    } else {
      session.unmute({ audio: true, video: false });
    }

    setMuted(targetState);
  };

  const toggleSpeakerMute = () => {
    setSpeakerMuted((prev) => {
      const next = !prev;
      if (remoteAudioRef.current) {
        remoteAudioRef.current.volume = next ? 0 : speakerVolume / 100;
      }
      return next;
    });
  };

  const toggleHold = () => {
    const session = sessionRef.current as any;
    if (!session) return;

    if (session.isLocalHeld?.() || session.isOnHold?.()?.local) {
      session.unhold?.();
      setHeld(false);
    } else {
      session.hold?.();
      setHeld(true);
    }
  };

  const pressDigit = (digit: string) => {
    playDtmfTone(digit, speakerVolume);
    setDialTarget((prev) => prev + digit);

    if (sessionRef.current && (callState === 'active' || callState === 'ringing' || callState === 'calling')) {
      sessionRef.current.sendDTMF(digit);
    }
  };

  const deleteLastDigit = () => {
    setDialTarget((prev) => prev.slice(0, -1));
  };

  const copyNumber = () => {
    if (dialTarget && typeof navigator !== 'undefined') {
      void navigator.clipboard.writeText(dialTarget);
    }
  };

  const makeCall = async () => {
    if (!settings?.sipDomain || !dialTarget.trim()) return;

    try {
      const targetUri = normalizeCallTarget(dialTarget, settings.sipDomain);
      setStatus('Connecting...');
      setCallState('calling');
      handleSetExpanded(true);

      if (!uaRef.current) {
        await phoneLifecycleRef.current.connectPhone();
      }

      if (uaRef.current) {
        uaRef.current.call(targetUri, {
          mediaConstraints: { audio: true, video: false },
          pcConfig: { iceServers: iceServersFromSettings(settings) },
        });
      }
    } catch {
      setStatus('Call Failed');
      setCallState('failed');
    }
  };

  const answerCall = () => {
    const session = sessionRef.current;
    if (!session) return;

    phoneLifecycleRef.current.stopIncomingRingTone();
    session.answer({
      mediaConstraints: { audio: true, video: false },
      pcConfig: { iceServers: iceServersFromSettings(settings) },
    });
    setIncomingPopupDismissed(true);
  };

  const declineCall = () => {
    const session = sessionRef.current;
    phoneLifecycleRef.current.stopIncomingRingTone();

    if (session) {
      session.terminate({ status_code: 486, reason_phrase: 'Busy Here' });
    }

    setIncomingPopupDismissed(true);
    setCallState('idle');
  };

  const hangupCall = () => {
    const session = sessionRef.current;
    phoneLifecycleRef.current.stopIncomingRingTone();

    if (session) {
      session.terminate();
    }

    setCallState('idle');
  };

  const dismissIncomingPopup = () => {
    setIncomingPopupDismissed(true);
  };

  const ready = isWebphoneReady(settings, webphone);
  const callBusy = callState !== 'idle';
  const callActive = callState === 'active';
  const incomingCallWaiting = callState === 'incoming';
  const showIncomingPopup = incomingCallWaiting && !incomingPopupDismissed;
  const canCall = ready && !callBusy && Boolean(dialTarget.trim());

  const callPeerNumber = remoteParty || dialTarget;
  const callPeerName = webphone?.displayName || callPeerNumber;

  return [
    {
      shouldRender: shouldActivate && ready,
      expanded,
      setExpanded: handleSetExpanded,
      activeTab,
      setActiveTab,
      connectionState,
      callState,
      status,
      dialTarget,
      setDialTarget,
      displayNumber: dialTarget,
      remoteParty,
      muted,
      speakerMuted,
      held,
      autoAnswer,
      setAutoAnswer,
      doNotDisturb,
      setDoNotDisturb,
      callLogs,
      logsLoading,
      micVolume,
      speakerVolume,
      setMicVolumeLevel,
      setSpeakerVolumeLevel,
      micLevel,
      speakerLevel,
      timerLabel,
      mediaNotice,
      ready,
      callBusy,
      callActive,
      incomingCallWaiting,
      showIncomingPopup,
      canCall,
      callPeerNumber,
      callPeerName,
      phoneDisplayName: webphone?.displayName || webphone?.extension || 'WebPhone',
      keypad,
      toggleMute,
      toggleSpeakerMute,
      toggleHold,
      pressDigit,
      deleteLastDigit,
      copyNumber,
      makeCall,
      answerCall,
      declineCall,
      hangupCall,
      dismissIncomingPopup,
    },
    remoteAudioRef,
  ] as const;
}

function readBooleanPreference(key: string, fallback: boolean): boolean {
  if (typeof window === 'undefined') return fallback;
  const value = safeStorage.getItem(key);
  if (value === null) return fallback;
  return value === 'true';
}

function readNumberPreference(key: string, fallback: number): number {
  if (typeof window === 'undefined') return fallback;
  const value = Number(safeStorage.getItem(key));
  return Number.isFinite(value) ? value : fallback;
}

function writePreference(key: string, value: unknown): void {
  if (typeof window === 'undefined') return;
  safeStorage.setItem(key, String(value));
}

export function formatWebphoneLogTime(dateStr?: string | null): string {
  if (!dateStr) return '';
  const date = new Date(dateStr);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

"use client";

import { useI18n } from "@/i18n/I18nContext";
import { X, ChevronLeft, ChevronRight, Download } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/Button";
import { useState } from "react";
import type { DashboardDrilldownRecord } from "../models/dashboard-types";
import { exportToCSV } from "../utils/export-utils";

interface DashboardDrilldownPanelProps {
  open: boolean;
  onClose: () => void;
  title: string;
  subtitle?: string;
  records: DashboardDrilldownRecord[];
  isLoading?: boolean;
}

export function DashboardDrilldownPanel({ open, onClose, title, subtitle, records, isLoading }: DashboardDrilldownPanelProps) {
  const { lang } = useI18n();
  const isRtl = lang === "ar";
  const [page, setPage] = useState(1);
  const itemsPerPage = 50;

  const totalPages = Math.ceil((records?.length || 0) / itemsPerPage);
  const visibleRecords = records?.slice((page - 1) * itemsPerPage, page * itemsPerPage) || [];

  return (
    <AnimatePresence>
      {open && (
        <div className="fixed inset-0 z-50 overflow-hidden flex">
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm"
            onClick={onClose}
          />

          {/* Slide Over Panel */}
          <motion.div
            initial={{ x: isRtl ? "-100%" : "100%" }}
            animate={{ x: 0 }}
            exit={{ x: isRtl ? "-100%" : "100%" }}
            transition={{ type: "spring", bounce: 0, duration: 0.4 }}
            className={`absolute ${isRtl ? "left-0 border-r" : "right-0 border-l"} top-0 bottom-0 w-full md:w-[600px] lg:w-[800px] bg-white dark:bg-slate-900 dark:border-slate-800 shadow-2xl flex flex-col`}
            dir={isRtl ? "rtl" : "ltr"}
          >
            {/* Header */}
            <div className="flex items-center justify-between p-6 border-b dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900">
              <div>
                <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                  {title}
                </h2>
                {subtitle && (
                  <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
                    {subtitle}
                  </p>
                )}
              </div>
              <div className="flex items-center gap-2">
                <Button variant="secondary" className="gap-2" onClick={() => exportToCSV(records, title)}>
                  <Download className="w-4 h-4" />
                  {isRtl ? "export" : "Export"}
                </Button>
                <button
                  onClick={onClose}
                  className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>
            </div>

            {/* Content Table */}
            <div className="flex-1 overflow-auto p-6 relative">
              {isLoading ? (
                <div className="absolute inset-0 flex items-center justify-center bg-white/50 dark:bg-slate-900/50">
                  <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
                </div>
              ) : records.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full text-slate-500">
                  <p>{isRtl ? "No data available." : "No data available."}</p>
                </div>
              ) : (
                <div className="border dark:border-slate-800 rounded-lg overflow-hidden">
                  <table className="w-full text-sm text-left">
                    <thead className="bg-slate-50 dark:bg-slate-800/50 text-slate-600 dark:text-slate-300 font-medium border-b dark:border-slate-800">
                      <tr>
                        {Object.keys(visibleRecords[0] || {}).map((key) => (
                          <th key={key} className="px-4 py-3 whitespace-nowrap">
                            {key.replace(/_/g, " ").replace(/\b\w/g, l => l.toUpperCase())}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y dark:divide-slate-800 bg-white dark:bg-slate-900">
                      {visibleRecords.map((row, i) => (
                        <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                          {Object.values(row).map((val: any, j) => (
                            <td key={j} className="px-4 py-3 text-slate-700 dark:text-slate-300 max-w-[200px] truncate">
                              {typeof val === 'object' ? JSON.stringify(val) : String(val)}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>

            {/* Pagination Footer */}
            {!isLoading && records.length > 0 && (
              <div className="p-4 border-t dark:border-slate-800 bg-slate-50 dark:bg-slate-900 flex items-center justify-between">
                <p className="text-sm text-slate-500">
                  {isRtl ? "an offer" : "Showing"} {((page - 1) * itemsPerPage) + 1} {isRtl ? "to" : "to"} {Math.min(page * itemsPerPage, records.length)} {isRtl ? "from" : "of"} {records.length} {isRtl ? "register" : "records"}
                </p>
                <div className="flex items-center gap-2">
                  <Button 
                    variant="secondary" 
                    disabled={page === 1}
                    onClick={() => setPage(p => Math.max(1, p - 1))}
                  >
                    <ChevronLeft className={`w-4 h-4 ${isRtl ? "rotate-180" : ""}`} />
                  </Button>
                  <Button 
                    variant="secondary" 
                    disabled={page === totalPages}
                    onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                  >
                    <ChevronRight className={`w-4 h-4 ${isRtl ? "rotate-180" : ""}`} />
                  </Button>
                </div>
              </div>
            )}
          </motion.div>
        </div>
      )}
    </AnimatePresence>
